PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, permissions TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role_id INTEGER NOT NULL REFERENCES roles(id), verified INTEGER DEFAULT 1, two_factor_enabled INTEGER DEFAULT 0, two_factor_secret TEXT, failed_logins INTEGER DEFAULT 0, locked_until TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, refresh_hash TEXT NOT NULL, device TEXT, ip TEXT, last_used_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS login_history (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), email TEXT, ip TEXT, device TEXT, success INTEGER NOT NULL, reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, token_hash TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, company_name TEXT NOT NULL, contact_name TEXT, email TEXT, phone TEXT, address TEXT, status TEXT DEFAULT 'active', owner_id TEXT REFERENCES users(id), tags TEXT DEFAULT '[]', notes TEXT, custom_fields TEXT DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, full_name TEXT NOT NULL, company TEXT, email TEXT, phone TEXT, source TEXT DEFAULT 'website', score INTEGER DEFAULT 0, stage TEXT DEFAULT 'new', service_type TEXT, owner_id TEXT REFERENCES users(id), follow_up_at TEXT, message TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS deals (id TEXT PRIMARY KEY, title TEXT NOT NULL, customer_id TEXT REFERENCES customers(id), lead_id TEXT REFERENCES leads(id), value REAL DEFAULT 0, stage TEXT DEFAULT 'qualification', probability INTEGER DEFAULT 20, expected_close TEXT, owner_id TEXT REFERENCES users(id), notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS communications (id TEXT PRIMARY KEY, customer_id TEXT REFERENCES customers(id), lead_id TEXT REFERENCES leads(id), type TEXT NOT NULL, subject TEXT, content TEXT, occurred_at TEXT NOT NULL, user_id TEXT REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, manager_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employees (id TEXT PRIMARY KEY, employee_number TEXT UNIQUE, full_name TEXT NOT NULL, email TEXT, phone TEXT, department_id TEXT REFERENCES departments(id), position TEXT, salary REAL DEFAULT 0, status TEXT DEFAULT 'active', hire_date TEXT, vacation_days REAL DEFAULT 0, sick_days REAL DEFAULT 0, performance_notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id) ON DELETE CASCADE, date TEXT NOT NULL, check_in TEXT, check_out TEXT, status TEXT DEFAULT 'present', notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(employee_id,date));
CREATE TABLE IF NOT EXISTS payroll (id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id), month TEXT NOT NULL, base_salary REAL DEFAULT 0, bonuses REAL DEFAULT 0, deductions REAL DEFAULT 0, tax REAL DEFAULT 0, net_salary REAL DEFAULT 0, status TEXT DEFAULT 'draft', paid_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, customer_id TEXT REFERENCES customers(id), manager_id TEXT REFERENCES users(id), status TEXT DEFAULT 'planning', start_date TEXT, deadline TEXT, progress INTEGER DEFAULT 0, budget REAL DEFAULT 0, spent REAL DEFAULT 0, description TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS milestones (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, due_date TEXT, completed INTEGER DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, project_id TEXT REFERENCES projects(id), customer_id TEXT REFERENCES customers(id), assigned_to TEXT REFERENCES users(id), priority TEXT DEFAULT 'medium', status TEXT DEFAULT 'todo', due_date TEXT, progress INTEGER DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bank_accounts (id TEXT PRIMARY KEY, name TEXT NOT NULL, bank TEXT, account_number TEXT, balance REAL DEFAULT 0, currency TEXT DEFAULT 'ILS', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transactions (id TEXT PRIMARY KEY, type TEXT NOT NULL, category TEXT, amount REAL NOT NULL, date TEXT NOT NULL, description TEXT, customer_id TEXT REFERENCES customers(id), project_id TEXT REFERENCES projects(id), bank_account_id TEXT REFERENCES bank_accounts(id), recurring INTEGER DEFAULT 0, vat_rate REAL DEFAULT 17, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, number TEXT UNIQUE NOT NULL, customer_id TEXT REFERENCES customers(id), issue_date TEXT NOT NULL, due_date TEXT, subtotal REAL DEFAULT 0, vat_rate REAL DEFAULT 17, vat_amount REAL DEFAULT 0, total REAL DEFAULT 0, status TEXT DEFAULT 'draft', paid_at TEXT, notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoice_items (id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity REAL DEFAULT 1, unit_price REAL DEFAULT 0, total REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), type TEXT NOT NULL, title TEXT NOT NULL, message TEXT, link TEXT, read_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, name TEXT NOT NULL, stored_name TEXT, mime_type TEXT, size INTEGER DEFAULT 0, entity_type TEXT, entity_id TEXT, access_role TEXT DEFAULT 'employee', uploaded_by TEXT REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, before_data TEXT, after_data TEXT, ip TEXT, device TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job_listings (id TEXT PRIMARY KEY, title TEXT NOT NULL, location TEXT, category TEXT, employment_type TEXT, salary_range TEXT, description TEXT, requirements TEXT, status TEXT DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job_applications (id TEXT PRIMARY KEY, job_id TEXT REFERENCES job_listings(id), job_title TEXT, full_name TEXT NOT NULL, email TEXT, phone TEXT, experience TEXT, status TEXT DEFAULT 'pending', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_leads_stage ON leads(stage); CREATE INDEX IF NOT EXISTS idx_deals_stage ON deals(stage); CREATE INDEX IF NOT EXISTS idx_tasks_due ON tasks(due_date,status); CREATE INDEX IF NOT EXISTS idx_transactions_date ON transactions(date); CREATE INDEX IF NOT EXISTS idx_invoices_status_due ON invoices(status,due_date); CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at); CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,read_at);
